/**
 * Canonical US college directory for the Dream Colleges picker (Build My Path + Profile).
 *
 * Source: NCES / IPEDS institutional directory, regenerated by `npm run sync:colleges` into
 * `colleges.generated.json` (~3,900 degree-granting 2-year and 4-year institutions in the 50
 * states + DC, keyed by the federal UNITID). Nothing here is hand-typed — see
 * scripts/sync-colleges.mjs for the scope rules and scripts/data/college-aliases.json for the
 * curated abbreviations (UCLA, SJSU, Cal Poly SLO, …).
 *
 * The JSON is loaded on demand (`loadColleges`) so the landing page never pays for it; the
 * payload is compact tuples decoded here into `College` objects.
 */
export type CollegeControl = "public" | "private-nonprofit" | "private-for-profit" | null;
export type CollegeLevel = "4-year" | "2-year";

export interface College {
  /** Federal IPEDS UNITID — stable across releases. */
  id: number;
  /** Display name, e.g. "University of California, Berkeley". */
  name: string;
  city: string;
  /** Two-letter state code. */
  state: string;
  control: CollegeControl;
  level: CollegeLevel;
  hbcu: boolean;
  tribal: boolean;
  /** Hostname (+ path) without scheme, or null when IPEDS has none. */
  website: string | null;
  /** Abbreviations, former names and the raw IPEDS name — searched, never displayed as the title. */
  aliases: string[];
}

/** [id, name, city, state, control, level, flags, website, aliases] — see the `fields` key in the JSON. */
export type CollegeRecord = [number, string, string, string, number, number, number, string, string[]];

export interface CollegeDirectoryPayload {
  source: string;
  sourceUrl: string;
  retrievedAt: string;
  count: number;
  records: CollegeRecord[];
}

const CONTROL: Record<number, CollegeControl> = { 1: "public", 2: "private-nonprofit", 3: "private-for-profit" };

export function decodeCollege(record: CollegeRecord): College {
  const [id, name, city, state, control, level, flags, website, aliases] = record;
  return {
    id,
    name,
    city,
    state,
    control: CONTROL[control] ?? null,
    level: level === 2 ? "2-year" : "4-year",
    hbcu: (flags & 1) === 1,
    tribal: (flags & 2) === 2,
    website: website || null,
    aliases,
  };
}

export function decodeColleges(payload: Pick<CollegeDirectoryPayload, "records">): College[] {
  return payload.records.map(decodeCollege);
}

let directoryPromise: Promise<College[]> | null = null;

/** Fetches and decodes the directory once per session; safe to call from several components. */
export function loadColleges(): Promise<College[]> {
  if (!directoryPromise) {
    directoryPromise = import("./colleges.generated.json")
      .then((module) => decodeColleges((module.default ?? module) as unknown as CollegeDirectoryPayload))
      .catch((error) => {
        directoryPromise = null; // allow a retry after a transient network failure
        throw error;
      });
  }
  return directoryPromise;
}

const CONTROL_LABEL: Record<Exclude<CollegeControl, null>, string> = {
  public: "Public",
  "private-nonprofit": "Private",
  "private-for-profit": "Private, for-profit",
};

/** "Berkeley, CA · Public · 4-year" — enough context to tell same-named colleges apart. */
export function describeCollege(college: College): string {
  const parts = [`${college.city}, ${college.state}`];
  if (college.control) parts.push(CONTROL_LABEL[college.control]);
  parts.push(college.level);
  if (college.hbcu) parts.push("HBCU");
  if (college.tribal) parts.push("Tribal college");
  return parts.join(" · ");
}
